import{_ as d,o as r,c as o,ag as n}from"./chunks/framework.KxDd3USm.js";const c=JSON.parse('{"title":"04.5 设计模式分类与意图速查 ★★★","description":"","frontmatter":{},"headers":[],"relativePath":"04-面向对象与设计模式/05-设计模式框架.md","filePath":"04-面向对象与设计模式/05-设计模式框架.md"}'),s={name:"04-面向对象与设计模式/05-设计模式框架.md"};function e(a,t,g,h,i,l){return r(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="_04-5-设计模式分类与意图速查-★★★" tabindex="-1">04.5 设计模式分类与意图速查 ★★★ <a class="header-anchor" href="#_04-5-设计模式分类与意图速查-★★★" aria-label="Permalink to &quot;04.5 设计模式分类与意图速查 ★★★&quot;">​</a></h1><h3 id="_4-1-23-种模式的分类框架-先背骨架" tabindex="-1">4.1 23 种模式的分类框架（先背骨架） <a class="header-anchor" href="#_4-1-23-种模式的分类框架-先背骨架" aria-label="Permalink to &quot;4.1 23 种模式的分类框架（先背骨架）&quot;">​</a></h3><p>模式按<strong>目的</strong>分三类——这本身就回答了&quot;为什么有 23 种&quot;：<strong>创建型</strong>管&quot;对象怎么造出来&quot;（5 种）、<strong>结构型</strong>管&quot;对象怎么组装起来&quot;（7 种）、<strong>行为型</strong>管&quot;对象怎么交互分工&quot;（11 种）。</p><p>口诀（自编，按序号背）：</p><ul><li>创建型 5：<strong>单原工抽建</strong>（单例、原型、工厂方法、抽象工厂、构建器）</li><li>结构型 7：<strong>适桥组外装享代</strong>（适配器、桥接、组合、外观、装饰器、享元、代理）</li><li>行为型 11：<strong>责命解迭中，备观状策模访</strong>（职责链、命令、解释器、迭代器、中介者、备忘录、观察者、状态、策略、模板方法、访问者）</li></ul><p><strong>数量口诀</strong>：<strong>5 / 7 / 11</strong>（连着念&quot;五七十一&quot;）。考题问&quot;下列属于创建型的有几个&quot;，先数出 5 个就够了，不必逐个回忆意图。</p><p><strong>另一种分类维度（算考点，别忽略）</strong>：按<strong>作用范围</strong>分<strong>类模式</strong>与<strong>对象模式</strong>。类模式有 4 种：<strong>工厂方法、类适配器、模板方法、解释器</strong>。按 23 种“模式名称”去重后，其余 19 种可按对象方式实现；但<strong>适配器例外地同时有两种实现</strong>：类适配器借继承完成转换，对象适配器持有被适配者并委托调用。因此，若题目问“类模式”选类适配器；若问“对象模式”时，对象适配器也成立，不能把“其余 19”误当成对象实现形式的总数。</p><h3 id="_4-2-23-种意图速查表-背-意图一句话-速记词" tabindex="-1">4.2 23 种意图速查表（背&quot;意图一句话 + 速记词&quot;） <a class="header-anchor" href="#_4-2-23-种意图速查表-背-意图一句话-速记词" aria-label="Permalink to &quot;4.2 23 种意图速查表（背&quot;意图一句话 + 速记词&quot;）&quot;">​</a></h3><p><strong>创建型（管出生）</strong>：</p><table tabindex="0"><thead><tr><th>模式</th><th>意图一句话</th><th>速记词</th></tr></thead><tbody><tr><td>Singleton 单例</td><td>保证一个类<strong>只有一个实例</strong>，提供全局访问点</td><td>唯一实例</td></tr><tr><td>Prototype 原型</td><td>通过<strong>拷贝</strong>原型来创建新对象</td><td>克隆</td></tr><tr><td>Factory Method 工厂方法</td><td>定义创建对象的接口，<strong>由子类决定</strong>实例化哪个类</td><td>动态生产对象</td></tr><tr><td>Abstract Factory 抽象工厂</td><td>创建<strong>一系列相关对象</strong>，无需指定具体类</td><td>成系列生产</td></tr><tr><td>Builder 构建器</td><td>复杂对象的<strong>构建过程与表示分离</strong>，分步构造</td><td>分步组装</td></tr></tbody></table><p><strong>结构型（管组装）</strong>：</p><table tabindex="0"><thead><tr><th>模式</th><th>意图一句话</th><th>速记词</th></tr></thead><tbody><tr><td>Adapter 适配器</td><td><strong>转换接口</strong>，使原本不兼容的类协同工作</td><td>转换接口</td></tr><tr><td>Bridge 桥接</td><td>把<strong>抽象与实现分离</strong>（两个维度），使它们独立变化</td><td>继承树拆两维</td></tr><tr><td>Composite 组合</td><td>把对象组成<strong>树形结构</strong>表示&quot;整体—部分&quot;，单个和组合对象使用一致</td><td>树形目录</td></tr><tr><td>Facade 外观</td><td>给复杂子系统提供一个<strong>统一的高层接口</strong></td><td>统一窗口</td></tr><tr><td>Decorator 装饰器</td><td><strong>动态地给对象附加职责</strong>，比继承灵活</td><td>附加职责</td></tr><tr><td>Flyweight 享元</td><td><strong>共享</strong>大量细粒度对象，节省内存</td><td>共享细粒度</td></tr><tr><td>Proxy 代理</td><td>为对象提供一个<strong>替身</strong>以控制对它的访问</td><td>间接访问</td></tr></tbody></table><p><strong>行为型（管交互）</strong>：</p><table tabindex="0"><thead><tr><th>模式</th><th>意图一句话</th><th>速记词</th></tr></thead><tbody><tr><td>Chain of Responsibility 职责链</td><td>请求沿处理者<strong>链条传递</strong>，直到被处理</td><td>传递职责</td></tr><tr><td>Command 命令</td><td>把请求封装成对象，支持<strong>撤销、日志、排队</strong></td><td>请求变对象</td></tr><tr><td>Interpreter 解释器</td><td>给定语言文法，用解释器<strong>解释句子</strong></td><td>解释语言</td></tr><tr><td>Iterator 迭代器</td><td>顺序访问聚合元素而<strong>不暴露内部表示</strong></td><td>逐个访问</td></tr><tr><td>Mediator 中介者</td><td>封装对象间交互，各对象<strong>不必显式互相引用</strong></td><td>中介转达</td></tr><tr><td>Memento 备忘录</td><td>保存对象状态，需要时<strong>恢复</strong></td><td>存档恢复</td></tr><tr><td>Observer 观察者</td><td>一对多依赖，状态变化时<strong>通知所有依赖者</strong></td><td>订阅—通知</td></tr><tr><td>State 状态</td><td>对象在<strong>状态改变时改变行为</strong></td><td>状态变行为变</td></tr><tr><td>Strategy 策略</td><td>封装一系列<strong>算法</strong>，使它们可<strong>互相替换</strong></td><td>算法可换</td></tr><tr><td>Template Method 模板方法</td><td>父类定<strong>算法骨架</strong>，某些步骤延迟到子类</td><td>骨架在父类</td></tr><tr><td>Visitor 访问者</td><td>不改动类的前提下给类<strong>添加新操作</strong></td><td>外加操作</td></tr></tbody></table><h3 id="_4-3-低频模式也要有画面-最小场景与排除法" tabindex="-1">4.3 低频模式也要有画面：最小场景与排除法 <a class="header-anchor" href="#_4-3-低频模式也要有画面-最小场景与排除法" aria-label="Permalink to &quot;4.3 低频模式也要有画面：最小场景与排除法&quot;">​</a></h3><p>下表不要求死背代码；先用“要解决的矛盾”建立画面，再用右列排除最像的干扰项。</p><table tabindex="0"><thead><tr><th>模式</th><th>最小场景</th><th>不要误判为</th></tr></thead><tbody><tr><td>原型</td><td>已有一份复杂报表模板，要复制后只改日期和标题</td><td>工厂方法：它重点是由子类决定造哪种产品，不是复制现成对象</td></tr><tr><td>抽象工厂</td><td>一次创建同一主题的深色按钮、深色菜单和深色对话框</td><td>工厂方法：后者通常只负责一个产品等级</td></tr><tr><td>构建器</td><td>按“选座、配餐、保险”分步组装一份旅行订单</td><td>工厂：它直接给成品，不强调可变的组装步骤</td></tr><tr><td>组合</td><td>文件夹和文件都可执行“计算大小”，文件夹递归汇总子项</td><td>迭代器：后者只负责遍历，不把整体和部分统一成同一接口</td></tr><tr><td>外观</td><td><code>CheckoutFacade</code> 统一调用库存、支付、物流三个子系统</td><td>适配器：适配器改一个接口，外观是为多个子系统收敛入口</td></tr><tr><td>享元</td><td>文本编辑器共享同一种字形对象，把坐标等外部状态按次传入</td><td>缓存：缓存保留计算结果；享元的核心是共享可复用对象状态</td></tr><tr><td>职责链</td><td>报销依次由组长、部门经理、财务审批，不能处理就转交</td><td>中介者：中介者集中协调多对象，不是沿固定链逐级传递</td></tr><tr><td>命令</td><td>编辑器把“删除一行”封成对象，放入队列并支持 <code>undo</code></td><td>备忘录：备忘录保存状态快照，不是封装一次操作</td></tr><tr><td>解释器</td><td>用简单规则语言解释 <code>年龄 &gt;= 18 AND 已实名</code></td><td>策略：策略替换算法，不负责按文法解释一句表达式</td></tr><tr><td>迭代器</td><td>用同一 <code>next()</code> 接口遍历数组和链表，而不暴露内部结构</td><td>组合：组合解决树形整体—部分关系</td></tr><tr><td>中介者</td><td>聊天室由服务器转发消息，用户彼此不直接持有引用</td><td>观察者：观察者是状态变化后的一对多通知</td></tr><tr><td>备忘录</td><td>绘图软件在保存点记录画布状态，失败时整体恢复</td><td>命令：命令通常通过反向操作撤销一次动作</td></tr><tr><td>状态</td><td>订单在“待支付、已支付、已发货”时对同一操作有不同反应</td><td>策略：策略通常由客户主动选择，状态多由对象条件触发切换</td></tr><tr><td>模板方法</td><td>父类固定“读取—处理—输出”流程，子类只实现处理细节</td><td>策略：策略把整个算法作为可替换对象</td></tr><tr><td>访问者</td><td>员工、部门类型稳定，却要不断新增“算税、导出、审计”等操作</td><td>观察者：观察者通知订阅者，不解决给稳定对象结构新增操作</td></tr></tbody></table>',17)])])}const u=d(s,[["render",e]]);export{c as __pageData,u as default};
